# Public install assets only; no account or inventory data.
ICONS = {180: '', 192: '', 512: ''}
SERVICE_WORKER = 'const CACHE=\'hourstack-app-assets-v1\';\nconst ASSETS=[\'/app-icon-180.png\',\'/app-icon-192.png\',\'/app-icon-512.png\'];\nself.addEventListener(\'install\',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()));});\nself.addEventListener(\'activate\',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith(\'hourstack-app-assets-\')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()));});\nself.addEventListener(\'fetch\',event=>{\n const url=new URL(event.request.url);\n if(url.origin!==self.location.origin||event.request.method!==\'GET\')return;\n if(ASSETS.includes(url.pathname)){event.respondWith(caches.match(event.request).then(hit=>hit||fetch(event.request)));return;}\n // Never cache authenticated HTML, product data, API responses or passwords.\n if(event.request.mode===\'navigate\'&&url.pathname===\'/\'){\n  event.respondWith(fetch(event.request).catch(()=>new Response(\'<!doctype html><html lang="zh-Hant"><meta name="viewport" content="width=device-width,initial-scale=1"><title>鐘點站名錶監控</title><body style="font:17px system-ui;background:#f5f6f8;color:#152337;padding:35px"><h1 style="font-size:25px">目前無法連線</h1><p>請確認網路連線後重新開啟，查看最新商品資料。</p><button style="font:inherit;padding:12px 20px" onclick="location.reload()">重新連線</button></body></html>\',{status:503,headers:{\'Content-Type\':\'text/html; charset=utf-8\',\'Cache-Control\':\'no-store\'}})));\n }\n});\n'
